import React from "react";

export default function About() {
  return (
    <div className="about-page">

      {/* HERO */}
      <div className="hero">
        <h1>
          I’m a developer who turns <span>ideas into systems</span>.
        </h1>
      </div>

      {/* MAIN */}
      <div className="main">

        {/* LEFT SIDE - FUTURISTIC TIMELINE */}
        <div className="story timeline">

          <div className="timeline-line"></div>

          <div className="t-item">
            <div className="t-dot"></div>
            <div className="t-content">
              <h2>Problem Deconstruction</h2>
              <p>
                I break complex systems into smaller logical modules before writing code.
                This helps me design clean and scalable architectures.
              </p>
            </div>
          </div>

          <div className="t-item">
            <div className="t-dot"></div>
            <div className="t-content">
              <h2>Build Cycle Approach</h2>
              <p>
                My workflow follows an iterative loop: build → test → refine → optimize.
                Each cycle improves system stability and performance.
              </p>
            </div>
          </div>

          <div className="t-item">
            <div className="t-dot"></div>
            <div className="t-content">
              <h2>Engineering Focus</h2>
              <p>
                I focus on full-stack development, UI precision, backend logic,
                and building real-world scalable applications.
              </p>
            </div>
          </div>

        </div>

        {/* RIGHT SIDE (UNCHANGED) */}
        <div className="side">

          <div className="card main-card">
            <h2>👤 About Me</h2>

            <p>
              I am an Information Technology student passionate about building
              practical and scalable software solutions.
            </p>

            <p>
              I enjoy understanding systems deeply and converting ideas into
              clean, structured applications.
            </p>
          </div>

          <div className="card">
            <h3>🎓 Education</h3>

            <p>B.Tech – Information Technology</p>
            <p className="muted">Panimalar Engineering College</p>

            <div className="row">
              <span>2023 – 2027</span>
              <span className="cgpa">CGPA: 8.81</span>
            </div>
          </div>

        </div>

      </div>

      {/* STATS (UNCHANGED) */}
      <div className="stats">

        <div className="stat-card">
          <h3>5+</h3>
          <p>Projects</p>
        </div>

        <div className="stat-card">
          <h3>1+</h3>
          <p>Internships</p>
        </div>

        <div className="stat-card">
          <h3>3+</h3>
          <p>Certifications</p>
        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 20px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
        }

        .hero h1 {
          font-size: 44px;
          line-height: 1.3;
        }

        .hero span {
          color: #38BDF8;
        }

        .main {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 40px;
          margin-top: 50px;
        }

        /* ============================= */
        /* FUTURISTIC TIMELINE (LEFT) */
        /* ============================= */

        .timeline {
          position: relative;
          padding-left: 30px;
        }

        .timeline-line {
          position: absolute;
          left: 10px;
          top: 0;
          width: 2px;
          height: 100%;
          background: linear-gradient(#38BDF8, transparent);
          box-shadow: 0 0 10px #38BDF8;
        }

        .t-item {
          display: flex;
          gap: 14px;
          margin-bottom: 28px;
          position: relative;
        }

        .t-dot {
          width: 12px;
          height: 12px;
          background: #38BDF8;
          border-radius: 50%;
          box-shadow: 0 0 12px #38BDF8;
          margin-top: 6px;
          flex-shrink: 0;
        }

        .t-content {
          background: rgba(255,255,255,0.03);
          border: 1px solid rgba(56,189,248,0.15);
          padding: 14px 16px;
          border-radius: 12px;
          transition: 0.3s;
        }

        .t-content:hover {
          transform: translateX(6px);
          border-color: rgba(56,189,248,0.4);
          box-shadow: 0 0 18px rgba(56,189,248,0.15);
        }

        .t-content h2 {
          color: #38BDF8;
          font-size: 18px;
          margin-bottom: 6px;
        }

        .t-content p {
          color: #cbd5e1;
          line-height: 1.6;
        }

        /* RIGHT SIDE (UNCHANGED) */
        .side {
          display: flex;
          flex-direction: column;
          gap: 16px;
        }

        .card {
          padding: 18px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
        }

        .main-card {
          border: 1px solid rgba(56,189,248,0.3);
          box-shadow: 0 0 18px rgba(56,189,248,0.08);
        }

        h2, h3 {
          color: #38BDF8;
          margin-bottom: 10px;
        }

        p {
          color: #cbd5e1;
          line-height: 1.6;
        }

        .muted {
          color: #94a3b8;
        }

        .row {
          display: flex;
          justify-content: space-between;
          margin-top: 10px;
        }

        .cgpa {
          color: #38BDF8;
          font-weight: 600;
        }

        /* STATS */
        .stats {
          margin-top: 50px;
          display: flex;
          gap: 20px;
        }

        .stat-card {
          flex: 1;
          text-align: center;
          padding: 20px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
        }

        .stat-card h3 {
          color: #38BDF8;
          font-size: 28px;
        }

        .stat-card p {
          color: #94a3b8;
        }

        @media (max-width: 900px) {
          .main {
            grid-template-columns: 1fr;
          }

          .stats {
            flex-direction: column;
          }

          .hero h1 {
            font-size: 32px;
          }
        }

      `}</style>

    </div>
  );
}
